using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using Microsoft.CodeAnalysis;

namespace CodeFusion.Data.Generator;

/// <summary>Writes a context's generated file: the SQL constants, and per query its statements, binder, readers and interceptor.</summary>
sealed class Emitter
{
    static readonly SymbolDisplayFormat Full = SymbolDisplayFormat.FullyQualifiedFormat
        .AddMiscellaneousOptions(SymbolDisplayMiscellaneousOptions.IncludeNullableReferenceTypeModifier);

    readonly StringBuilder _b = new();
    readonly Dictionary<string, string> _names = new(StringComparer.Ordinal);
    readonly StringBuilder _nameFields = new();
    readonly INamedTypeSymbol _context;
    readonly string _provider, _statement;
    /// <summary>The provider declares Alone itself. C# calls a static virtual member's default only through a type
    /// parameter, never on the provider type, so for a provider without it the statement stays as it is: which is
    /// what the default does.</summary>
    readonly bool _alone;
    /// <summary>The provider declares KeyedUpdate itself (as with Alone, the default can't be called on its type).</summary>
    readonly bool _keyed;
    int _indent;

    public Emitter(INamedTypeSymbol context, INamedTypeSymbol provider, ITypeSymbol statement)
    {
        _context = context;
        _provider = provider.ToDisplayString(Full);
        _statement = statement.ToDisplayString(Full);
        _alone = Declares(provider, "Alone");
        _keyed = Declares(provider, "KeyedUpdate");
    }

    static bool Declares(INamedTypeSymbol provider, string name) =>
        provider.GetMembers(name).Any(m => m is IMethodSymbol { IsStatic: true, DeclaredAccessibility: Accessibility.Public });

    public static string Type(ITypeSymbol t) => t.ToDisplayString(Full);

    void Line(string s = "")
    {
        if (s.Length > 0) _b.Append(' ', _indent * 4).Append(s);
        _b.Append('\n');
    }

    void Open(string s)
    {
        if (s != "{") Line(s);
        Line("{");
        _indent++;
    }

    void Close(string s = "}")
    {
        _indent--;
        Line(s);
    }

    string Name(string json)
    {
        if (_names.TryGetValue(json, out var field)) return field;
        field = "N" + Names.Number(_names.Count);
        _names[json] = field;
        _nameFields.Append("        static readonly global::System.Text.Json.JsonEncodedText ").Append(field)
            .Append(" = global::System.Text.Json.JsonEncodedText.Encode(").Append(Names.Literal(json)).Append(");\n");
        return field;
    }

    public string Emit(IReadOnlyList<Compiled> queries)
    {
        string ns = _context.ContainingNamespace.IsGlobalNamespace ? "" : _context.ContainingNamespace.ToDisplayString();
        string contextName = _context.Name;
        var head = new StringBuilder();
        head.Append("// <auto-generated/> by CodeFusion.Data's query generator.\n#nullable enable\n#pragma warning disable\n\n");
        // the SQL of every query, readable as constants
        if (ns.Length > 0) head.Append("namespace ").Append(ns).Append("\n{\n");
        var containers = new List<INamedTypeSymbol>();
        for (var t = _context; t is not null; t = t.ContainingType) containers.Insert(0, t);
        foreach (var c in containers) head.Append("    partial ").Append(c.TypeKind == TypeKind.Struct ? "struct " : "class ").Append(c.Name).Append(TypeParams(c)).Append("\n    {\n");
        head.Append("        /// <summary>The SQL of each query method, as the query generator wrote it.</summary>\n");
        head.Append("        public static class QuerySql\n        {\n");
        foreach (var q in queries)
            for (int i = 0; i < q.Statements.Count; i++)
            {
                var s = q.Statements[i];
                string what = Xml(q.Method.Name) + (i == 0 ? "" : ", statement " + Names.Number(i + 1));
                head.Append("            /// <summary>").Append(what).Append(".</summary>\n            public const string ").Append(s.Name).Append(" = ").Append(Names.Literal(s.Sql)).Append(";\n");
                head.Append("            /// <summary>The types of ").Append(what).Append("'s parameters, $1 first.</summary>\n            public static global::System.ReadOnlySpan<global::CodeFusion.Data.DataType> ")
                    .Append(s.Name).Append("Parameters => [").Append(string.Join(", ", s.Params.Select(p => "global::CodeFusion.Data.DataType." + DataType(p.Kind)))).Append("];\n");
            }
        head.Append("        }\n");
        foreach (var _ in containers) head.Append("    }\n");
        if (ns.Length > 0) head.Append("}\n");
        head.Append('\n');
        head.Append("namespace System.Runtime.CompilerServices\n{\n    [global::System.AttributeUsage(global::System.AttributeTargets.Method, AllowMultiple = true)]\n");
        head.Append("    file sealed class InterceptsLocationAttribute(int version, string data) : global::System.Attribute { }\n}\n\n");

        _indent = 1;
        for (int i = 0; i < queries.Count; i++) Query(queries[i], i);
        var all = new StringBuilder(head.ToString());
        all.Append("namespace CodeFusion.Data.Generated\n{\n");
        all.Append("    file static class ").Append(contextName).Append("Queries\n    {\n");
        all.Append(_nameFields);
        all.Append(_b);
        all.Append("    }\n}\n");
        return all.ToString();
    }

    static string TypeParams(INamedTypeSymbol t) => t.TypeParameters.Length == 0 ? "" : "<" + string.Join(", ", t.TypeParameters.Select(p => p.Name)) + ">";

    static string Xml(string s) => s.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;");

    // ---------- one query ----------

    void Query(Compiled q, int n)
    {
        var m = q.Method;
        string sqlOf = _context.ToDisplayString(Full) + ".QuerySql.";
        string id = "Q" + Names.Number(n);
        Line();
        Line($"// {m.Name}");
        for (int i = 0; i < q.Statements.Count; i++)
        {
            var s = q.Statements[i];
            var types = s.Params.Select(p => "global::CodeFusion.Data.DataType." + DataType(p.Kind));
            // one row by its key: a provider that declares KeyedUpdate may run a group's run of these as one
            // statement (never one that runs alone: those never share a group)
            string made = s.Keyed is { } k && _keyed && !q.RunsAlone && q.Shape == Shape.Write && q.Statements.Count == 1
                ? $"{_provider}.KeyedUpdate({sqlOf}{s.Name}, {Names.Literal(k.Table)}, {Names.Literal(k.Key)}, {k.KeyParameter}, " +
                  $"new string[] {{ {string.Join(", ", k.Columns.Select(Names.Literal))} }}, new int[] {{ {string.Join(", ", k.ColumnParameters)} }}{string.Concat(types.Select(t => ", " + t))})"
                : $"{_provider}.Statement({sqlOf}{s.Name}{string.Concat(types.Select(t => ", " + t))})";
            Line($"static readonly {_statement} {id}S{i} = {(q.RunsAlone && _alone ? $"{_provider}.Alone({made})" : made)};");
        }

        // the interceptor: each value the statements bind is computed first, so one that throws (a method of the
        // app's, a null's .Value) leaves no command half built; then the command is rented and bound. A value
        // several statements use (an insert's key set by a call, a ThenIf's condition, an inlined call's argument)
        // is computed once, and each binds that local
        string ret = Type(m.ReturnType);
        var pars = m.Parameters.Select(p => $"{Modifier(p)}{Type(p.Type)} {Names.Identifier(p.Name)}").ToList();
        var values = new List<(string Type, string Name)>();
        var guards = new Dictionary<Guard, string>();
        var computed = new Dictionary<string, List<(string Name, string Type, Guard? Under)>>();
        var locals = new List<string?[]>();
        foreach (var call in q.Calls) Line(call.Attribute + $" // {System.IO.Path.GetFileName(call.File)}:{call.Line}");
        Open($"public static {ret} {Names.Identifier(m.Name)}(this {Type(_context)} __context{string.Concat(pars.Select(p => ", " + p))})");
        string GuardOf(Guard g)
        {
            if (guards.TryGetValue(g, out var name)) return name;
            string? outer = g.Outer is null ? null : GuardOf(g.Outer);
            guards[g] = name = "__c" + Names.Number(guards.Count);
            Line(outer is null ? $"bool {name} = {g.Code};" : $"bool {name} = {outer} && ({g.Code});");
            values.Add(("bool", name));
            return name;
        }
        // an inlined call's impure argument, in its own type: each use converts from it, as C# does at the call
        void Argument(Argument a)
        {
            string? when = a.Under is null ? null : GuardOf(a.Under);
            Line(when is null ? $"var {a.Name} = {a.Code};" : $"var {a.Name} = {when} ? {a.Code} : default!;");
        }
        for (int i = 0; i < q.Statements.Count; i++)
        {
            var s = q.Statements[i];
            // the arguments of a call made before this statement's ThenIf, whose condition may read them
            foreach (var a in q.Arguments.Where(a => a.Before == i && a.Under != s.Condition)) Argument(a);
            string? when = i > 0 && s.Condition is { } g ? GuardOf(g) : null;
            var names = new string?[s.Params.Count];
            // in the order C# makes them, which the order of the SQL's parameters needn't be, with the arguments of
            // the calls inlined on the way
            var order = Enumerable.Range(0, s.Params.Count).Select(j => (s.Params[j].Made, Param: j, Argument: (Argument?)null))
                .Concat(q.Arguments.Where(a => a.Before == i && a.Under == s.Condition).Select(a => (a.Made, Param: -1, Argument: (Argument?)a)))
                .OrderBy(x => x.Made);
            foreach (var (_, j, argument) in order)
            {
                if (argument is not null)
                {
                    Argument(argument);
                    continue;
                }
                var p = s.Params[j];
                string type = Type(p.Type);
                // computed already for a statement that runs whenever this one does: the same local. An impure value
                // is bound in one type (the translator refuses another), so only a pure one is computed again here
                var earlier = computed.TryGetValue(p.Key, out var c) ? c.Where(e => Guard.Within(s.Condition, e.Under)) : [];
                if (earlier.FirstOrDefault(e => e.Type == type).Name is { } same)
                {
                    names[j] = same;
                    continue;
                }
                string name = names[j] = $"__v{i}_{j}";
                // a statement under ThenIf binds its values only when its condition holds: computed then only
                Line(when is null ? $"{type} {name} = {p.Code};" : $"{type} {name} = {when} ? {p.Code} : default!;");
                values.Add((type, name));
                if (c is null) computed[p.Key] = c = new();
                c.Add((name, type, s.Condition));
            }
            locals.Add(names);
        }
        foreach (var a in q.Arguments.Where(a => a.Before >= q.Statements.Count)) Argument(a);
        Line($"var __command = {_provider}.{(q.IsWrite ? "Write" : "Read")}(__context, {id}S0);");
        Line($"return new {ret}(__context, {id}Bind(__command{string.Concat(values.Select(v => ", " + v.Name))}), {id}Ops.Instance);");
        Close();

        // the binder: generic over the provider's command, so each parameter is a direct call into it
        Open($"static global::CodeFusion.Data.PendingCommand {id}Bind<TCommand>(TCommand __command{string.Concat(values.Select(v => $", {(RefStruct(v.Type) ? "scoped " : "")}{v.Type} {v.Name}"))}) " +
            $"where TCommand : global::CodeFusion.Data.IDataCommand<{_statement}>, allows ref struct");
        for (int i = 0; i < q.Statements.Count; i++)
        {
            var s = q.Statements[i];
            if (i > 0)
            {
                if (s.Condition is not null) Open($"if ({guards[s.Condition]})");
                Line($"__command.Then({id}S{i});");
            }
            for (int j = 0; j < s.Params.Count; j++) Bind(s.Params[j], locals[i][j]!, $"__p{i}_{j}");
            if (i > 0 && s.Condition is not null) Close();
        }
        Line("return __command.Hold();");
        Close();

        Ops(q, id);
        JsonReader(q, id);
        CopyReader(q, id);
    }

    static bool RefStruct(string type) => type.StartsWith("global::System.ReadOnlySpan<", StringComparison.Ordinal) || type.StartsWith("global::System.Span<", StringComparison.Ordinal);

    static string Modifier(IParameterSymbol p) => (p.ScopedKind == ScopedKind.ScopedValue ? "scoped " : "") + p.RefKind switch
    {
        RefKind.In => "in ",
        RefKind.Ref => "ref ",
        RefKind.Out => "out ",
        RefKind.RefReadOnlyParameter => "ref readonly ",
        _ => p.IsParams ? "params " : "",
    };

    static string DataType(ParamType k) => k switch
    {
        ParamType.Int64 => "Int64",
        ParamType.Int32 => "Int32",
        ParamType.Boolean => "Boolean",
        ParamType.Double => "Double",
        ParamType.Timestamp => "Timestamp",
        ParamType.TextArray => "TextArray",
        _ => "Text",
    };

    /// <summary>Binds <paramref name="p"/>, whose value is <paramref name="code"/>; <paramref name="local"/> names its
    /// value once tested for null.</summary>
    void Bind(Param p, string code, string local)
    {
        switch (p.Kind)
        {
            case ParamType.TextArray:
                if (p.Nullable) Open($"if ({code} is {{ }} {local})");
                else
                {
                    Open("{");
                    Line($"var {local} = {code};");
                }
                Line("__command.BeginTextArray();");
                // the list is read as it is bound, after the command was rented: a lazy one may throw, and the
                // command goes back unrun
                Open("try");
                Line($"foreach (var __e in {local}) __command.Element(__e.Span);");
                Close();
                Open("catch");
                Line("__command.Discard();");
                Line("throw;");
                Close();
                Line("__command.EndTextArray();");
                if (p.Nullable)
                {
                    Close();
                    Line("else __command.Null();");
                }
                else Close();
                return;
            case ParamType.Span:
                Line($"__command.Text({code});");
                return;
        }
        string Value(string v) => p.Kind switch
        {
            ParamType.Int64 => $"__command.Int64({v});",
            ParamType.Int32 => $"__command.Int32({v});",
            ParamType.Boolean => $"__command.Boolean({v});",
            ParamType.Double => $"__command.Double({v});",
            ParamType.Timestamp => $"__command.Timestamp({v});",
            ParamType.Text => $"__command.Text({v}.Span);",
            ParamType.String => $"__command.Text(global::System.MemoryExtensions.AsSpan({v}));",
            _ => throw new InvalidOperationException(),
        };
        if (p.Nullable)
        {
            Line($"if ({code} is {{ }} {local}) {Value(local)}");
            Line("else __command.Null();");
        }
        else Line(Value(code));
    }

    // ---------- the run-time half ----------

    void Ops(Compiled q, string id)
    {
        string kind = q.Shape switch
        {
            Shape.Many => "Many",
            Shape.Page => "Page",
            Shape.Write => "Write",
            _ => "One",
        };
        const string D = "global::CodeFusion.Data.";
        Open($"sealed class {id}Ops : {D}QueryOps");
        Line($"public static readonly {id}Ops Instance = new();");
        Line($"public override string Name => {Names.Literal(_context.Name + "." + q.Method.Name)};");
        Line($"public override {D}ResultKind Kind => {D}ResultKind.{kind};");
        Line($"public override bool IsWrite => {(q.IsWrite ? "true" : "false")};");
        if (q.HasSource) Line("public override bool HasSource => true;");
        Line($"public override global::System.Threading.Tasks.ValueTask<{D}DataResult> RunJson(in {D}PendingCommand command, {D}RowState state, global::System.Threading.CancellationToken aborted) => {_provider}.Run<{id}Json>(command, state, aborted);");
        if (q.Shape is Shape.One or Shape.WriteOf)
            Line($"public override global::System.Threading.Tasks.ValueTask<{D}DataResult> RunCopy(in {D}PendingCommand command, {D}RowState state, global::System.Threading.CancellationToken aborted) => {_provider}.Run<{id}Copy>(command, state, aborted);");
        else
            Line($"public override global::System.Threading.Tasks.ValueTask<{D}DataResult> RunCopy(in {D}PendingCommand command, {D}RowState state, global::System.Threading.CancellationToken aborted) => throw new global::System.NotSupportedException(\"only One and Write results can be awaited\");");
        Line($"public override void Discard(in {D}PendingCommand command) => {_provider}.Discard(command);");
        var begin = new List<string>();
        var end = new List<string>();
        switch (q.Shape)
        {
            case Shape.One or Shape.WriteOf:
            {
                string? wrap = q.View?.Envelope ?? q.ListName;
                if (wrap is not null)
                {
                    begin.Add("json.WriteStartObject();");
                    begin.Add($"json.WritePropertyName({Name(wrap)});");
                    end.Add("json.WriteEndObject();");
                }
                break;
            }
            case Shape.Many:
                if (q.ListName is not null)
                {
                    begin.Add("json.WriteStartObject();");
                    begin.Add($"json.WriteStartArray({Name(q.ListName)});");
                    end.Add("json.WriteEndArray();");
                    end.Add("json.WriteEndObject();");
                }
                else
                {
                    begin.Add("json.WriteStartArray();");
                    end.Add("json.WriteEndArray();");
                }
                break;
            case Shape.Page:
                begin.Add("json.WriteStartObject();");
                begin.Add($"json.WriteStartArray({Name(q.ListName ?? "items")});");
                end.Add("json.WriteEndArray();");
                end.Add($"json.WriteNumber({Name(q.CountName ?? "count")}, result.Value);");
                end.Add("json.WriteEndObject();");
                break;
        }
        if (begin.Count > 0)
        {
            Open("public override void Begin(global::System.Text.Json.Utf8JsonWriter json)");
            foreach (var l in begin) Line(l);
            Close();
            Open($"public override void End(global::System.Text.Json.Utf8JsonWriter json, in {D}DataResult result)");
            foreach (var l in end) Line(l);
            Close();
        }
        Close();
    }

    const string ReadSignature = "public static long Read<TRow>(scoped in TRow row, object? state) where TRow : global::CodeFusion.Data.IDataRow, allows ref struct";

    void JsonReader(Compiled q, string id)
    {
        Open($"sealed class {id}Json : global::CodeFusion.Data.IRowReader");
        Open(ReadSignature);
        if (q.Shape == Shape.Write)
        {
            Line("return 0;");
            Close();
            Close();
            return;
        }
        Line("var rows = (global::CodeFusion.Data.RowState)state!;");
        Line("var json = rows.Json;");
        switch (q.Shape)
        {
            case Shape.One or Shape.WriteOf:
                Line("if (rows.Seen++ > 0) return rows.First; // the first row is the result");
                if (q.Marker == Marker.Written) Line($"if (row.IsNull({q.MarkerColumn})) return rows.First = global::CodeFusion.Data.RowState.Refused;");
                Value(q, 0);
                Line("return rows.First = 0;");
                break;
            case Shape.Many:
                if (q.Marker == Marker.ChildKey) Line($"if (row.IsNull({q.MarkerColumn})) return 0; // the source row has no children");
                Value(q, 0);
                Line("return 0;");
                break;
            case Shape.Page:
                Open($"if (!row.IsNull({q.MarkerColumn})) // an empty page is one row with its count");
                Value(q, 0);
                Close();
                Line($"return row.GetInt64({q.CountColumn});");
                break;
        }
        Close();
        Close();
    }

    void Value(Compiled q, int column)
    {
        if (q.View is { } v) View(v, column, null);
        else Line(ScalarValue(q.Scalar!.Value, column));
    }

    void View(ViewInfo v, int column, string? name)
    {
        Line(name is null ? "json.WriteStartObject();" : $"json.WriteStartObject({Name(name)});");
        foreach (var m in v.Members)
        {
            if (m.Nested is { } nested)
            {
                if (!m.Ignored) View(nested, column, m.JsonName);
                column += nested.Width;
                continue;
            }
            if (!m.Ignored) Line(ScalarProperty(m.Kind, m.JsonName, column));
            column++;
        }
        Line("json.WriteEndObject();");
    }

    string ScalarProperty(ValueKind k, string json, int c)
    {
        string method = k.Scalar switch
        {
            Scalar.Text => "Text",
            Scalar.Timestamp => "Timestamp",
            Scalar.Raw => "Raw",
            Scalar.Boolean => "Boolean",
            Scalar.Double or Scalar.Single => "Double",
            _ => "Int64",
        };
        return $"global::CodeFusion.Data.RowJson.{(k.Nullable ? "Nullable" : "")}{method}(json, {Name(json)}, row, {c});";
    }

    static string ScalarValue(ValueKind k, int c)
    {
        string method = k.Scalar switch
        {
            Scalar.Text => "TextValue",
            Scalar.Timestamp => "TimestampValue",
            Scalar.Raw => "RawValue",
            Scalar.Boolean => "BooleanValue",
            Scalar.Double or Scalar.Single => "DoubleValue",
            _ => "Int64Value",
        };
        return $"global::CodeFusion.Data.RowJson.{method}(json, row, {c});";
    }

    void CopyReader(Compiled q, string id)
    {
        if (q.Shape is not (Shape.One or Shape.WriteOf)) return;
        string t = Type(q.Row!);
        Open($"sealed class {id}Copy : global::CodeFusion.Data.IRowReader");
        Open(ReadSignature);
        Line($"var slot = (global::CodeFusion.Data.RowSlot<{t}>)state!;");
        Line("if (slot.HasValue) return 0; // the first row is the result");
        if (q.Marker == Marker.Written) Line($"if (row.IsNull({q.MarkerColumn})) return global::CodeFusion.Data.RowState.Refused;");
        var texts = new List<(int Column, bool Json)>();
        Texts(q, texts);
        Line(texts.Count == 0 ? "var bytes = default(global::CodeFusion.ArenaBytes);"
            : $"var bytes = global::CodeFusion.Data.RowCopy.Allocate(slot, {string.Join(" + ", texts.Select(t => $"global::CodeFusion.Data.RowCopy.{(t.Json ? "JsonLength" : "Length")}(row, {t.Column})"))});");
        Line("int at = 0;");
        int column = 0;
        string value = q.View is { } v ? Construct(v, ref column) : CopyScalar(q.Scalar!.Value, column);
        Line($"slot.Set({value});");
        Line("return 0;");
        Close();
        Close();
    }

    /// <summary>The columns an awaited row copies into the arena: text, and JSON.</summary>
    static void Texts(Compiled q, List<(int Column, bool Json)> into)
    {
        if (q.View is null)
        {
            if (q.Scalar!.Value.Scalar is Scalar.Text or Scalar.Raw) into.Add((0, q.Scalar.Value.Scalar == Scalar.Raw));
            return;
        }
        int c = 0;
        void Walk(ViewInfo v)
        {
            foreach (var m in v.Members)
            {
                if (m.Nested is { } n) Walk(n);
                else
                {
                    if (m.Kind.Scalar is Scalar.Text or Scalar.Raw) into.Add((c, m.Kind.Scalar == Scalar.Raw));
                    c++;
                }
            }
        }
        Walk(q.View);
    }

    static string Construct(ViewInfo v, ref int column)
    {
        var values = new Dictionary<string, string>();
        foreach (var m in v.Members)
        {
            if (m.Nested is { } n) values[m.Property.Name] = Construct(n, ref column);
            else values[m.Property.Name] = CopyScalar(m.Kind, column++);
        }
        string type = Type(v.Type);
        if (v.Constructor is { } ctor)
            return $"new {type}({string.Join(", ", ctor.Parameters.Select(p => values[v.Members.First(m => string.Equals(m.Property.Name, p.Name, StringComparison.OrdinalIgnoreCase)).Property.Name]))})";
        return $"new {type} {{ {string.Join(", ", v.Members.Select(m => $"{Names.Identifier(m.Property.Name)} = {values[m.Property.Name]}"))} }}";
    }

    static string CopyScalar(ValueKind k, int c)
    {
        const string R = "global::CodeFusion.Data.RowCopy.";
        bool n = k.Nullable;
        return k.Scalar switch
        {
            Scalar.Text => n ? $"{R}NullableText(row, {c}, bytes, ref at)" : $"{R}Text(row, {c}, bytes, ref at)",
            Scalar.Raw => n ? $"{R}NullableRaw(row, {c}, bytes, ref at)" : $"{R}Raw(row, {c}, bytes, ref at)",
            Scalar.Timestamp => n ? $"{R}NullableTimestamp(row, {c})" : $"row.GetTimestamp({c})",
            Scalar.Boolean => n ? $"{R}NullableBoolean(row, {c})" : $"row.GetBoolean({c})",
            Scalar.Double => n ? $"{R}NullableDouble(row, {c})" : $"row.GetDouble({c})",
            Scalar.Single => n ? $"(float?){R}NullableDouble(row, {c})" : $"(float)row.GetDouble({c})",
            Scalar.Int64 => n ? $"{R}NullableInt64(row, {c})" : $"row.GetInt64({c})",
            Scalar.Int32 => n ? $"(int?){R}NullableInt64(row, {c})" : $"(int)row.GetInt64({c})",
            Scalar.Int16 => n ? $"(short?){R}NullableInt64(row, {c})" : $"(short)row.GetInt64({c})",
            _ => throw new InvalidOperationException(),
        };
    }
}
